"use client"

// src/components/UserManager.js
import { useEffect, useState } from "react"
import axios from "axios"
import "./UserManager.css"

function UserManager() {
  const [users, setUsers] = useState([])
  const [form, setForm] = useState({ name: "", email: "", area: "" })
  const [message, setMessage] = useState("")
  const [isEditing, setIsEditing] = useState(false)
  const [editUserId, setEditUserId] = useState(null)

  // Áreas disponibles para seleccionar
  const areas = ["Administración", "Ventas", "Desarrollo", "Soporte", "Marketing", "Recursos Humanos"]

  useEffect(() => {
    axios
      .get("http://localhost:5000/users")
      .then((res) => setUsers(res.data))
      .catch((err) => console.error(err))
  }, [])

  useEffect(() => {
    axios
      .get("http://localhost:5000/users")
      .then((res) => {
        console.log("Usuarios cargados:", res.data)
        setUsers(res.data)
      })
      .catch((err) => console.error(err))
  }, [])

  const handleSubmit = (e) => {
    e.preventDefault()

    if (isEditing) {
      // Actualizar usuario existente usando POST en lugar de PUT
      axios
        .post(`http://localhost:5000/users/update/${editUserId}`, form)
        .then((res) => {
          setUsers(users.map((user) => (user._id === editUserId ? res.data : user)))
          setForm({ name: "", email: "", area: "" })
          setIsEditing(false)
          setEditUserId(null)
          setMessage("Usuario actualizado con éxito")
          setTimeout(() => setMessage(""), 3000)
        })
        .catch((err) => {
          console.error(err)
          setMessage("Error al actualizar usuario")
        })
    } else {
      // Agregar nuevo usuario
      axios
        .post("http://localhost:5000/users", form)
        .then((res) => {
          setUsers([...users, res.data])
          setForm({ name: "", email: "", area: "" })
          setMessage("Usuario agregado con éxito")
          setTimeout(() => setMessage(""), 3000)
        })
        .catch((err) => {
          console.error(err)
          setMessage("Error al agregar usuario")
        })
    }
  }

  const handleDelete = (id) => {
    console.log("ID a eliminar:", id)
    axios
      .delete(`http://localhost:5000/users/${id}`)
      .then(() => {
        setUsers(users.filter((user) => user._id !== id))
        setMessage("Usuario eliminado con éxito")
        setTimeout(() => setMessage(""), 3000)
      })
      .catch((err) => {
        console.error(err)
        setMessage("Error al eliminar usuario")
      })
  }

  const handleEdit = (user) => {
    console.log("Usuario a editar:", user)
    setForm({
      name: user.name,
      email: user.email,
      area: user.area || "", // Usar área existente o vacío si no existe
    })
    setIsEditing(true)
    setEditUserId(user._id)
  }

  const cancelEdit = () => {
    setForm({ name: "", email: "", area: "" })
    setIsEditing(false)
    setEditUserId(null)
  }

  return (
    <div className="user-manager">
      <h2>Gestión de Usuarios</h2>

      <form onSubmit={handleSubmit} className="user-form">
        <div className="input-group">
          <input
            type="text"
            placeholder="Nombre completo"
            value={form.name}
            onChange={(e) => setForm({ ...form, name: e.target.value })}
            required
          />
          <input
            type="email"
            placeholder="Correo electrónico"
            value={form.email}
            onChange={(e) => setForm({ ...form, email: e.target.value })}
            required
          />
          <select
            value={form.area}
            onChange={(e) => setForm({ ...form, area: e.target.value })}
            required
            className="area-select"
          >
            <option value="">Selecciona un área</option>
            {areas.map((area, index) => (
              <option key={index} value={area}>
                {area}
              </option>
            ))}
          </select>
          <div className="button-group">
            <button type="submit">{isEditing ? "✏️ Actualizar usuario" : "➕ Agregar usuario"}</button>
            {isEditing && (
              <button type="button" onClick={cancelEdit} className="cancel-btn">
                ❌ Cancelar
              </button>
            )}
          </div>
        </div>
      </form>

      {message && <div className="message">{message}</div>}

      <div className="table-container">
        <table className="users-table">
          <thead>
            <tr>
              <th>Nombre</th>
              <th>Correo electrónico</th>
              <th>Área</th>
              <th>Acciones</th>
            </tr>
          </thead>
          <tbody>
            {users.map((user, index) => (
              <tr key={index}>
                <td>{user.name}</td>
                <td>{user.email}</td>
                <td>{user.area || "No asignada"}</td>
                <td className="action-cell">
                  <button className="edit-btn" onClick={() => handleEdit(user)}>
                    ✏️ Editar
                  </button>
                  <button className="delete-btn" onClick={() => handleDelete(user._id)}>
                    🗑 Eliminar
                  </button>
                </td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>
    </div>
  )
}

export default UserManager
